select CAST( Dateadd(minute, cast(right(RIGHT('0000' +cast(t1.CreateTime as varchar(4)), 4),2) as int),Dateadd(hour, cast(left(RIGHT('0000' +cast(t1.CreateTime as varchar(4)), 4),2) as int),t1.CreateDate))AS varchar)[CreateDate], 1 as 'No', t0.DocEntry as [GR_DocEntry], t0.ItemCode, t0.Dscription, t0.Quantity, t0.U_belnrid as [WO], t6.U_I_LineType as [LineTypeMasias], t5.U_SAC_Output as [LINE], t3.DistNumber as [Batch], COALESCE(NULLIF(t6.U_I_Ac1Balls,'0'),NULLIF(t6.U_I_Ac2Balls,'0'),0) as [Ball], cast(ISNULL(IIF (t5.U_energyElectricity = '',0,t5.U_energyElectricity),0) as numeric) /10 as 'energyElectricity(KWh)', iif(t4.UDF1 = 'Y', 'QC','No' ) [QCStatus], case	when t7.[Good] > 0 then 'QC_Passed'	when t7.[NotFinish] > 0 then ''	when t7.[NotGood] > 0 then ''	else ''end	as [StatusQC]--, T8.WhsCode AS 'CurrentWhs' , ISNULL((	SELECT TOP 1 T8_SUB.WhsCode	FROM OBTQ T8_SUB 	WHERE T8_SUB.ItemCode = T3.ItemCode AND T8_SUB.SysNumber = T3.SysNumber and T8_SUB.WhsCode in ('WHS03','WHS01')),'QC') AS 'CurrentWhs' from IGN1 t0inner join OITL t1 on t0.DocEntry = t1.DocEntry and t0.ObjType = t1.DocTypeinner join ITL1 t2 on t1.LogEntry = t2.LogEntryinner join OBTN t3 on t3.AbsEntry = t2.MdAbsEntryleft join BEAS_QSFTHAUPT t4 on t0.ObjType = t4.BaseType and t4.BASEDOCENTRY = t0.DocEntry and t4.BASEBASETYPE = 'E'and t0.LineNum = t4.BASELINENUMinner join OIGN t5 on t5.DocEntry = t0.DocEntryleft join [@IOT_PARAMETERS] t6 on t6.Code = cast(t0.U_belnrid as nvarchar(10))+CAST(t0.U_belposid as nvarchar(10))left join (	select CHARGE_ID, BELNR_ID,DocEntry,	COUNT(CASE WHEN (Coalesce(Release,0) = '1') and PRUEFKZ = 'F' THEN 1 END) AS [Good],	COUNT(CASE WHEN (Coalesce(Release,0) = '0') and PRUEFKZ = 'O' THEN 1 END) AS [NotFinish],	COUNT(CASE WHEN (Coalesce(Release,0) = '0') and PRUEFKZ <> 'O' THEN 1 END) AS [NotGood]	from BEAS_QSFTMESSUNG group by CHARGE_ID, BELNR_ID,DocEntry) t7 	on t4.CHARGE_ID = t7.CHARGE_ID and t4.BELNR_ID = t7.BELNR_ID and t4.DocEntry = t7.DocEntry and UDF1 = 'Y'--INNER JOIN OBTQ T8 ON T8.ItemCode = T3.ItemCode AND T8.SysNumber = T3.SysNumber and T8.Quantity <> 0where U_belnrid is not null and U_belposid is not null and U_posid = 0and t1.DocDate >= [%0] and t1.DocDate <= [%1]and t3.DistNumber not in (	select in_t3.DistNumber	from IGE1 in_t0	inner join OITL in_t1 on in_t0.DocEntry = in_t1.DocEntry and in_t0.ObjType = in_t1.DocType	inner join ITL1 in_t2 on in_t1.LogEntry = in_t2.LogEntry	inner join OBTN in_t3 on in_t3.AbsEntry = in_t2.MdAbsEntry	where in_t0.U_belnrid = t0.U_belnrid  and in_t0.U_belposid = t0.U_belposid and in_t0.ItemCode = t0.ItemCode)order by  Dateadd(minute, cast(right(RIGHT('0000' +cast(t1.CreateTime as varchar(4)), 4),2) as int),Dateadd(hour, cast(left(RIGHT('0000' +cast(t1.CreateTime as varchar(4)), 4),2) as int),t1.CreateDate)) desc